package money

import (
	"fmt"
	"strconv"
)

// FormatCents renders a cent amount as a US dollar string: 123456 -> "$1234.56".
func FormatCents(cents int) string {
	sign := ""
	if cents < 0 {
		sign = "-"
		cents = -cents
	}
	return fmt.Sprintf("%s$%s.%02d", sign, strconv.Itoa(cents/100), cents%100)
}

