import java.util.Locale;
import java.util.UUID;

public final class WelcomeEmailService {
    private final UserRepository repository;
    private final EmailClient emailClient;

    public WelcomeEmailService(UserRepository repository, EmailClient emailClient) {
        this.repository = repository;
        this.emailClient = emailClient;
    }

    public User register(RegistrationRequest request) {
        String email = request.email().trim().toLowerCase(Locale.ROOT);
        User user = new User(UUID.randomUUID().toString(), request.displayName(), email);
        repository.save(user);
        emailClient.send(new EmailMessage(email, "Welcome, " + user.displayName() + "!"));
        return user;
    }
}

