use std::collections::BTreeMap;

#[derive(Debug, PartialEq, Eq)]
pub struct Config {
    pub listeners: Vec<String>,
    pub workers: usize,
    pub tls: bool,
}

#[derive(Debug, PartialEq, Eq)]
pub enum ConfigError {
    MissingValue { line: usize },
    UnknownKey { line: usize, key: String },
    InvalidNumber { line: usize, value: String },
}

impl Config {
    pub fn parse(input: &str) -> Result<Config, ConfigError> {
        let mut listeners = Vec::new();
        let mut workers = 1usize;
        let mut tls = true;

        for (index, raw_line) in input.lines().enumerate() {
            let line_number = index + 1;
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let (key, value) = line
                .split_once('=')
                .ok_or(ConfigError::MissingValue { line: line_number })?;
            let (key, value) = (key.trim(), value.trim());
            match key {
                "listen" => listeners.push(value.to_string()),
                "workers" => {
                    workers = value.parse().map_err(|_| ConfigError::InvalidNumber {
                        line: line_number,
                        value: value.to_string(),
                    })?;
                }
                "tls" => {
                    tls = value.parse().map_err(|_| ConfigError::InvalidNumber {
                        line: line_number,
                        value: value.to_string(),
                    })?;
                }
                other => {
                    return Err(ConfigError::UnknownKey {
                        line: line_number,
                        key: other.to_string(),
                    })
                }
            }
        }

        Ok(Config { listeners, workers, tls })
    }
}

