    @Test
    fun `load emits loading then ready with the computed total`() = runTest {
        val order = Order(id = "o1", lines = listOf(Line(unitPriceCents = 500, quantity = 3)))
        val viewModel = OrderViewModel(
            FakeOrderRepository(Result.success(order)),
            StandardTestDispatcher(testScheduler),
