import java.io.IOException
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

data class Line(val unitPriceCents: Int, val quantity: Int)

data class Order(val id: String, val lines: List<Line>) {
    fun totalCents(): Int = lines.sumOf { it.unitPriceCents * it.quantity }
}

interface OrderRepository {
    suspend fun findById(id: String): Result<Order>
}

sealed interface OrderUiState {
    data object Loading : OrderUiState
    data class Ready(val totalCents: Int) : OrderUiState
    data class Error(val message: String) : OrderUiState
}

class OrderViewModel(
    private val repository: OrderRepository,
    private val dispatcher: CoroutineDispatcher,
) {
    private val scope = CoroutineScope(dispatcher + SupervisorJob())
    private val _state = MutableStateFlow<OrderUiState>(OrderUiState.Loading)
    val state: StateFlow<OrderUiState> = _state.asStateFlow()

    fun load(orderId: String) {
        _state.value = OrderUiState.Loading
        scope.launch {
            val result = repository.findById(orderId)
            _state.value = result.fold(
                onSuccess = { OrderUiState.Ready(it.totalCents()) },
                onFailure = { OrderUiState.Error(it.message ?: "unknown error") },
            )
        }
    }
}

