import Foundation

public struct CartLine: Equatable {
    public enum ParseError: Error, Equatable {
        case malformed(String)
        case invalidQuantity(String)
        case invalidPrice(String)
    }

    public let quantity: Int
    public let unitPriceCents: Int

    public var subtotalCents: Int { quantity * unitPriceCents }

    public static func parse(_ text: String) throws -> CartLine {
        let parts = text.components(separatedBy: " x ")
        guard parts.count == 2 else { throw ParseError.malformed(text) }

        guard let quantity = Int(parts[0]), quantity > 0 else {
            throw ParseError.invalidQuantity(parts[0])
        }

        guard var price = Decimal(string: parts[1]), price >= 0 else {
            throw ParseError.invalidPrice(parts[1])
        }

        var rounded = Decimal()
        NSDecimalRound(&rounded, &price, 2, .plain)
        let cents = NSDecimalNumber(decimal: rounded * 100).intValue
        return CartLine(quantity: quantity, unitPriceCents: cents)
    }
}

