#include <limits.h>
#include <stdint.h>
#include <stdio.h>

static int failures = 0;

static void check(const char *name, int32_t got, int32_t want) {
    if (got != want) {
        printf("FAIL %s: got %d, want %d\n", name, got, want);
        failures += 1;
    }
}

static void test_saturates_at_the_maximum(void) {
    check("INT32_MAX + 1", sat_add_i32(INT32_MAX, 1), INT32_MAX);
    check("INT32_MAX + INT32_MAX", sat_add_i32(INT32_MAX, INT32_MAX), INT32_MAX);
}

static void test_saturates_at_the_minimum(void) {
    check("INT32_MIN - 1", sat_add_i32(INT32_MIN, -1), INT32_MIN);
    check("INT32_MIN + INT32_MIN", sat_add_i32(INT32_MIN, INT32_MIN), INT32_MIN);
}

static void test_interior_arithmetic_stays_exact(void) {
    check("zero identity", sat_add_i32(0, 7), 7);
    check("negative plus positive", sat_add_i32(-20, 5), -15);
    check("large but representable", sat_add_i32(1000000000, 1000000000), 2000000000);
}

int main(void) {
    test_saturates_at_the_maximum();
    test_saturates_at_the_minimum();
    test_interior_arithmetic_stays_exact();
    if (failures != 0) {
        printf("%d checks failed\n", failures);
        return 1;
    }
    printf("all checks passed\n");
    return 0;
}

