#include <limits.h>
#include <stdint.h>

/* Adds two int32 values, clamping the result into the int32 range instead of
   invoking signed overflow (undefined behavior). */
int32_t sat_add_i32(int32_t a, int32_t b) {
    int64_t sum = (int64_t)a + (int64_t)b;
    if (sum > INT32_MAX) {
        return INT32_MAX;
    }
    if (sum < INT32_MIN) {
        return INT32_MIN;
    }
    return (int32_t)sum;
}

defmodule OrderStateMachine do
  @moduledoc "Pure state machine for one order's lifecycle."

  @events ~w(pay ship deliver refund cancel)a

  @transitions %{
    pending: %{pay: :paid, cancel: :cancelled},
    paid: %{ship: :shipped, refund: :refunded},
    shipped: %{deliver: :delivered},
    delivered: %{},
    cancelled: %{},
    refunded: %{}
  }

  defstruct state: :pending

  @spec new() :: %__MODULE__{}
  def new, do: %__MODULE__{}

  @spec state(%__MODULE__{}) :: atom()
  def state(%__MODULE__{state: state}), do: state

  @spec apply_event(%__MODULE__{}, atom()) ::
          {:ok, %__MODULE__{}} | {:error, :invalid_transition | :unknown_event}
  def apply_event(%__MODULE__{state: state} = machine, event) do
    if event not in @events do
      {:error, :unknown_event}
    else
      case Map.fetch(@transitions[state], event) do
        {:ok, next} -> {:ok, %__MODULE__{machine | state: next}}
        :error -> {:error, :invalid_transition}
      end
    end
  end
end
